B.awY=s(["Dorada \u2192 lubina, pargo o 2 lomos de merluza (10 minutos)."],t.s)
B.bgs=new A.T("\xbfC\xf3mo la sirvo sin espinas?","Abre por el lomo con un cuchillo, levanta la carne de arriba, quita la espina central de una pieza y ya tienes la de abajo limpia.")
B.aGU=s([B.bgs],t.Wy)
B.b9Z=new A.a9(B.c8,B.awB,"P\xeddele al pescadero que te la limpie y quite las escamas. Horno a 200 \xb0C.","El ojo se pone blanco y la carne se separa f\xe1cil de la espina central (unos 15-18 minutos para una dorada de 400 g).",B.az7,B.atG,B.awY,"Mejor reci\xe9n hecha.",null,B.aGU)
B.aUn=s(["Bol","Escurridor","T\xe1per"],t.s)
