B.aAw=s(["Chorizo \u2192 bacon o carne picada."],t.s)
B.bbE=new A.a9(B.r,B.ay2,null,"Pasta al dente y salsa bien caliente; si gratinas, el queso dorado (5 minutos).",B.atv,B.j,B.aAw,null,null,B.p)
B.aom=s(["Fuente de horno","Sart\xe9n","Horno"],t.s)
B.aqv=s(["Capas: un poco de salsa en el fondo, placas, carne, bechamel\u2026 y termina con bechamel y queso.","D\xe9jala reposar 10 minutos antes de cortar: as\xed no se desmorona."],t.s)
