B.azq=s(["Jam\xf3n \u2192 chistorra o pimientos."],t.s)
B.bbp=new A.a9(B.r,B.av7,null,"Patatas doradas por fuera y tiernas por dentro; huevos con la clara cuajada y la yema l\xedquida.",B.aWU,B.aQM,B.azq,"Para comer al momento.",null,B.p)
B.aw0=s(["Horno","Fuente de horno","Sart\xe9n","Cuchara"],t.s)
