B.bbm=new A.a9(B.c8,B.aw0,"Horno a 200 \xb0C.","La carne de la berenjena est\xe1 blanda (20-25 minutos asadas) y el queso gratinado (5 minutos m\xe1s).",B.aAI,B.ati,B.aAc,"3 d\xedas en la nevera.",null,B.p)
B.awj=s(["Sart\xe9n","Bol grande"],t.s)
