B.awy=s(["Mermelada de melocot\xf3n \u2192 la que tengas."],t.s)
B.bbD=new A.a9(B.r,B.B3,null,null,B.aYl,B.j,B.awy,null,null,B.p)
B.aA8=s(["Cafetera","Cazo o microondas"],t.s)
